function solve(tier, day) {
    const supportResponseHours = {
        'standard': {
            'monday': 2,
            'tuesday': 2,
            'wednesday': 2,
            'thursday': 2,
            'friday': 2,
            'saturday': 4,
            'sunday': 8
        },
        'enterprise': {
            'monday': 1,
            'tuesday': 1,
            'wednesday': 1,
            'thursday': 1,
            'friday': 1,
            'saturday': 2,
            'sunday': 4
        }
    };

    const tierLower = tier.toLowerCase();
    const dayLower = day.toLowerCase();

    if (!supportResponseHours[tierLower] || !supportResponseHours[tierLower][dayLower]) {
        return null;
    }

    return supportResponseHours[tierLower][dayLower];
}
